"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0834-01-01:0":{"b": ["Abdullah ibn Tahir suppressed Muhammad ibn Qasim, who had rebelled at Talaqan.", "00591821"], "d": ["Abdullah ibn Tahir suppressed Muhammad ibn Qasim, who had rebelled at Talaqan.", "00591821"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0844-01-01:0":{"b": ["Abdullah ibn Tahir dies; his son Tahir II succeeds him", "d2235609"], "d": ["Abdullah ibn Tahir dies; his son Tahir II succeeds him", "d2235609"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0862-03-11:0":{"b": ["Tahir II dies; Muhammad ibn Tahir is appointed governor in his place (248/862).", "22af070e"], "d": ["Tahir II dies; Muhammad ibn Tahir is appointed governor in his place (248/862).", "22af070e"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0876-09-24:0":{"b": ["Ibn al-Saqiyya dies; his son Muhammad takes the throne (263, 876-77).", "89f473df"], "d": ["Ibn al-Saqiyya dies; his son Muhammad takes the throne (263, 876-77).", "89f473df"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0883-07-11:0":{"b": ["Muhammad dies; his uncle Elyesa' II succeeds to the emirate (270, 883).", "1a21eeb6"], "d": ["Muhammad dies; his uncle Elyesa' II succeeds to the emirate (270, 883).", "1a21eeb6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0903-07-01:0":{"b": ["The Qarmatians besiege Damascus; the leader Sahib al-Naqa Yahya is killed during the siege", "9b876cc8"], "d": ["Yahya, known as Sahib al-Naqa, one of the sons of Zikrawayh ibn Mihrawayh, was killed during the siege of Damascus in Sha'ban 290 (July 903); his brother Sahib al-Shama took his place and, after an unsuccessful attack on Aleppo, seized Hama, Homs, Ma'arrat al-Nu'man and Baalbek.", "9980a87c"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0906-01-01:0":{"b": ["The Qarmatian da'i Abu Ghanim plunders Busra, Tiberias and Hit, then enters Kufa; he is soon expelled", "7b175ddd"], "d": ["Abu Ghanim Abdullah ibn Sa'id and his men, sent by Zikrawayh to revive Qarmatism among the Banu Kalb, plundered settlements such as Busra, Adhri'at, Tiberias and Hit and attacked Damascus; failing to achieve success, they entered Kufa but were soon expelled from the city (293/906).", "e62c81d1"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0911-01-01:0":{"b": ["The Turfan Uighur state becomes independent", "d48689ad"], "d": ["The Turfan Uighur state becomes independent", "d48689ad"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0913-01-01:0":{"b": ["Abu Sa'id al-Jannabi is killed in an assassination arranged by Ubayd Allah al-Mahdi (301); his sons continue the state.", "dd507fc0"], "d": ["Abu Sa'id al-Jannabi is killed in an assassination arranged by Ubayd Allah al-Mahdi (301); his sons continue the state.", "dd507fc0"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0931-01-24:0":{"b": ["Abu Tahir hands the administration of Bahrain to a Persian whom he presented as the mahdi; the new mahdi is killed eighty days later", "1816f4a5"], "d": ["Abu Tahir al-Jannabi, who had taken Oman (318/930), the following year handed the administration of Bahrain to a Persian whom he had brought from Isfahan and presented to the people as the mahdi. When the Persian presented himself as a descendant of the ancient Persian Khosraus and a reformer of the Persian religion and put forward ideas against the Arabs, he was killed by Abu Tahir eighty days after being installed; this caused great bewilderment and dispersal among the Bahrain Qarmatians.", "919b72ac"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0935-01-01:0":{"b": ["Mardawij is killed in Isfahan by his Turkish soldiers; his brother Washmgir succeeds him (323/935).", "11355262"], "d": ["Mardawij is killed in Isfahan by his Turkish soldiers; his brother Washmgir succeeds him (323/935).", "11355262"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0944-01-01:0":{"b": ["Abu Tahir died (332); his brothers pursued a peaceful policy toward the Abbasids.", "4b409f1d"], "d": ["Abu Tahir died (332); his brothers pursued a peaceful policy toward the Abbasids.", "4b409f1d"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0957-12-01:0":{"b": ["Marzuban dies in Ramadan 346 (December 957); Justan succeeds him.", "90c5eee8"], "d": ["Marzuban dies in Ramadan 346 (December 957); Justan succeeds him.", "90c5eee8"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0962-01-01:0":{"b": ["The Uyghurs of Turfan (Kao-ch'ang) sent their first trade delegation of 42 people to China.", "f51160fd"], "d": ["The Uyghurs of Turfan (Kao-ch'ang) sent their first trade delegation of 42 people to China.", "f51160fd"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0966-01-01:0":{"b": ["Ibrahim is defeated by Vahsudan and takes refuge with Rukn al-Dawla (355/966).", "e5df11cd"], "d": ["Ibrahim is defeated by Vahsudan and takes refuge with Rukn al-Dawla (355/966).", "e5df11cd"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0967-01-01:0":{"b": ["Washmgir dies during a hunt (357/967).", "68f9525b"], "d": ["Washmgir dies during a hunt (357/967).", "68f9525b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0972-07-01:0":{"b": ["Hasan al-A'sam reoccupied Ramla and defeated a strong Fatimid army", "c3b5ad80"], "d": ["The Qarmatian leader Hasan al-A'sam reoccupied Ramla in Ramadan 361 (July 972) and defeated a strong Fatimid army; a year later he attacked Egypt by land and sea and besieged Cairo once more, but was defeated by al-Aziz Billah.", "f629e2e1"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0981-01-01:0":{"b": ["The Chinese envoy Wang Yande began traveling among the Uyghurs (981-984); his report is the main source on Turfan Uyghur culture.", "478d801b"], "d": ["The Chinese envoy Wang Yande began traveling among the Uyghurs (981-984); his report is the main source on Turfan Uyghur culture.", "478d801b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0985-01-01:0":{"b": ["The army that Mansur b. Buluggin sent against Fez and Sijilmasa failed (374, 985).", "85a5064b"], "d": ["The army that Mansur b. Buluggin sent against Fez and Sijilmasa failed (374, 985).", "85a5064b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0985-05-24:0":{"b": ["The Qarmatians of Bahrain occupied Kufa two years after Basra; they could not hold out against the Buyids and withdrew", "4b76d4b0"], "d": ["After the death of the Buyid Adud al-Dawla (372/983), the Qarmatians of Bahrain, wishing to display their strength in southern Iraq, attacked Basra in 373 (983-84) and made it pay tribute, and two years later they occupied Kufa; but they could not hold out against the Buyids and withdrew, and never again had a voice in Iraq.", "0451dba6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0991-01-01:0":{"b": ["Abu'l-Fath Muhammad b. Annaz began to rule at Hulwan", "b1809519"], "d": ["Abu'l-Fath Muhammad b. Annaz began to rule at Hulwan", "b1809519"]},
